def copier_fiches(reservations):
    copie = []
    for r in reservations:
        copie.append(r.copy())
    return copie

def annuler(reservations, identifiant):
    trouve = False
    for r in reservations:
        if r["id"] == identifiant and r["active"]:
            trouve = True
    if not trouve:
        return None
    copie = []
    for r in reservations:
        fiche = r.copy()
        if fiche["id"] == identifiant:
            fiche["active"] = False
        copie.append(fiche)
    return copie

def id_disponible(reservations, identifiant):
    for r in reservations:
        if r["id"] == identifiant:
            return False
    return True

def ids_uniques(reservations):
    vus = set()
    for r in reservations:
        if r["id"] in vus:
            return False
        vus.add(r["id"])
    return True
